// 只测原六角报价/处置域；没有Military10注册和真实World回合，不称可玩战果。
#include "resident/domains/military/military_rout_disposition.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {int checks=0;void check(bool ok,const char* why){++checks;if(!ok)throw std::runtime_error(why);}template<class T>T take(Outcome<T> value){if(!value.ok)throw std::runtime_error(value.error.original.code);return std::move(value.value);}}
int main(){try{
 MilitaryBattleCatalog catalog;BattlefieldDefinition field;field.id="field";for(Integer q=0;q<7;++q){HexCell cell;cell.q=q;cell.terrain="plain";field.cells.push_back(cell);}field.spawns={{0,{0,0},{}},{1,{6,0},{}}};field.exits=field.spawns;catalog.battlefields={field};TroopDefinition troop;troop.id="foot";troop.movement=2;troop.movement_costs["plain"]=1;catalog.troop_types={troop};MilitaryBattleRecord battle;battle.id="battle:1";battle.battlefield_id=field.id;battle.round=2;BattleUnit unit;unit.unit_id="unit";unit.army_id="army:1";unit.commander_actor_id="officer";unit.troop_type_id=troop.id;unit.position={4,0};unit.morale=0;unit.member_ids=unit.fit={"one","two"};BattleUnit enemy=unit;enemy.unit_id="enemy";enemy.army_id="army:2";enemy.commander_actor_id="opponent";enemy.side=1;enemy.position={6,0};enemy.morale=50;enemy.member_ids=enemy.fit={"three"};battle.units={unit,enemy};MilitaryRoutRetreatRule rule;
 auto retreat=take(quote_military_rout_retreat(battle,catalog,rule,unit.unit_id));check(retreat.exit_reachable&&retreat.can_progress&&retreat.destination==HexPoint{2,0}&&retreat.cost==2,"real original terrain limits retreat to two steps");check(battle.units[0].position==unit.position&&battle.units[0].fit==unit.fit,"quote is read-only");
 auto moved=battle;moved.units[0].position=retreat.destination;auto progress=take(resolve_military_rout_disposition(battle,moved,catalog,rule,{{unit.unit_id,1,1}}));check(progress.progress[0].blocked_rounds==0&&progress.battle.units[0].captured.empty(),"actual movement resets consecutive blocked rounds");
 auto blocked=battle;blocked.units[1].position={3,0};auto wait=take(quote_military_rout_retreat(blocked,catalog,rule,unit.unit_id));check(!wait.exit_reachable&&!wait.can_progress&&wait.adjacent_captor_unit_ids==std::vector<StableId>{enemy.unit_id},"real occupied corridor has actual adjacent captor");auto first=take(resolve_military_rout_disposition(blocked,blocked,catalog,rule,{{unit.unit_id,1,0}}));check(first.progress[0].blocked_rounds==1&&first.battle.units[0].fit==unit.fit,"one blocked completed round cannot capture");++blocked.round;auto second=take(resolve_military_rout_disposition(blocked,blocked,catalog,rule,first.progress));check(second.progress.empty()&&second.battle.units[0].fit.empty()&&second.battle.units[0].captured==unit.fit&&second.battle.units[0].dead.empty()&&second.battle.units[0].deserted.empty(),"two blocked rounds move original tokens to real captor only");
 auto no_captor=blocked;no_captor.units[1].morale=0;check(!quote_military_rout_retreat(no_captor,catalog,rule,unit.unit_id).value.adjacent_captor_unit_ids.size(),"mutual rout cannot invent a captor");auto bad=blocked;bad.units[0].position={0,0};check(!resolve_military_rout_disposition(blocked,bad,catalog,rule,first.progress).ok,"teleport to exit rejected");auto missing=rule;missing.blocked_rounds_before_capture=1;check(!validate_military_rout_rule(missing,field).ok,"immediate capture policy rejected");
 std::cout<<"MILITARY_ROUT_RETREAT="<<checks<<" FAILURES=0 SCOPE=DOMAIN_SOURCE\n";return 0;
 }catch(const std::exception& e){std::cerr<<"MILITARY_ROUT_RETREAT_FAIL "<<checks<<" "<<e.what()<<'\n';return 1;}}
